// StarBridge languages. The pages are written in Spanish; in English every visible text
// (static HTML, text set by the scripts, messages from the brain, canvas labels, dialogs) is
// looked up in window.I18N_EN (i18n-en.js, generated by tools/i18n/build.py) as it appears.
// Untranslated text simply stays in Spanish. Load i18n-en.js and this file in <head>.
(() => {
  'use strict';
  const DICT = window.I18N_EN || {};
  const LANGS = ['es', 'en'];
  const store = {
    get() { try { return localStorage.getItem('sb.lang'); } catch { return null; } },
    set(v) { try { localStorage.setItem('sb.lang', v); } catch { /* private mode */ } },
  };
  // ?lang= (the Android app opening its own page) wins and is remembered.
  const fromUrl = new URLSearchParams(location.search).get('lang');
  if (LANGS.includes(fromUrl)) store.set(fromUrl);
  const chosen = LANGS.includes(fromUrl) ? fromUrl : (LANGS.includes(store.get()) ? store.get() : null);
  const lang = chosen || ((navigator.language || 'es').toLowerCase().startsWith('es') ? 'es' : 'en');
  document.documentElement.lang = lang;

  const norm = (s) => s.replace(/\s+/g, ' ').trim();
  const exact = new Map();
  const templates = [];
  const reEsc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  for (const [k, v] of Object.entries(DICT)) {
    if (!k.includes('{}')) { exact.set(k, v); continue; }
    const parts = k.split('{}');
    templates.push({ prefix: parts[0], loose: !parts[0], re: new RegExp('^' + parts.map(reEsc).join('(.*?)') + '$', 's'), en: v });
  }
  // Most specific first: the longest literal prefix, then the longest key.
  templates.sort((a, b) => b.prefix.length - a.prefix.length || b.re.source.length - a.re.source.length);

  function fill(en, vals) {
    let i = 0;
    return en.replace(/\{(\d*)\}/g, (_, n) => (n ? vals[Number(n) - 1] : vals[i++]) ?? '');
  }
  function lookup(n, depth) {
    const hit = exact.get(n);
    if (hit !== undefined) return hit;
    for (const tp of templates) {
      if (tp.prefix && !n.startsWith(tp.prefix)) continue;
      const m = tp.re.exec(n);
      if (!m) continue;
      const vals = m.slice(1);
      // "{} de {}"-like keys only for short values (numbers, names), never for whole sentences.
      // A value must look like a value: a number, or a name (capital first), never Spanish words.
      if (tp.loose && vals.some((v) => v.split(' ').length > 4 || (/[a-záéíóúñ]/.test(v) && !/^[\p{Lu}\d+−-]/u.test(v)))) continue;
      return fill(tp.en, depth < 3 ? vals.map((v) => tr(v, depth + 1)) : vals);
    }
    // "Sirio · α CMa", "SO · 26° de altura · mag -1.44": each part on its own.
    if (depth < 3 && n.includes(' · ')) {
      const parts = n.split(' · ');
      const out = parts.map((p) => tr(p, depth + 1));
      if (out.some((p, i) => p !== parts[i])) return out.join(' · ');
    }
    return undefined;
  }
  const cache = new Map();
  function tr(s, depth = 0) {
    if (lang === 'es' || s == null) return s;
    const str = String(s);
    if (!/[A-Za-zÁÉÍÓÚáéíóúÑñ¿¡]/.test(str)) return str;
    const n = norm(str);
    let out = cache.get(n);
    if (out === undefined) {
      out = lookup(n, depth);
      if (out === undefined) out = null;
      if (cache.size > 8000) cache.clear();
      cache.set(n, out);
    }
    if (out === null) return str;
    if (n === str) return out;
    return (str.match(/^\s*/)[0]) + out + (str.match(/\s*$/)[0]);
  }

  // ------------------------------------------------------------------ the page itself
  const ATTRS = ['placeholder', 'title', 'aria-label', 'alt'];
  const SKIP = new Set(['SCRIPT', 'STYLE', 'TEXTAREA', 'PRE', 'CODE']);
  const seen = new WeakMap();
  function skipped(el) {
    for (let e = el; e && e.nodeType === 1; e = e.parentElement) {
      if (SKIP.has(e.tagName) || e.hasAttribute('data-no-i18n')) return true;
    }
    return false;
  }
  function textNode(node) {
    const v = node.nodeValue;
    if (!v || seen.get(node) === v) return;
    if (node.parentElement && skipped(node.parentElement)) return;
    const t = tr(v);
    if (t !== v) node.nodeValue = t;
    seen.set(node, node.nodeValue);
  }
  function element(el) {
    for (const a of ATTRS) {
      const v = el.getAttribute(a);
      if (v) { const t = tr(v); if (t !== v) el.setAttribute(a, t); }
    }
  }
  function walk(root) {
    if (root.nodeType === 3) { textNode(root); return; }
    if (root.nodeType !== 1 || skipped(root)) return;
    element(root);
    const w = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT, {
      acceptNode: (n) => (n.nodeType === 1 && (SKIP.has(n.tagName) || n.hasAttribute('data-no-i18n')) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT),
    });
    for (let n = w.nextNode(); n; n = w.nextNode()) { if (n.nodeType === 3) textNode(n); else element(n); }
  }
  if (lang !== 'es') {
    new MutationObserver((list) => {
      for (const m of list) {
        if (m.type === 'childList') m.addedNodes.forEach(walk);
        else if (m.type === 'characterData') textNode(m.target);
        else if (m.type === 'attributes' && m.target.nodeType === 1) element(m.target);
      }
    }).observe(document.documentElement, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ATTRS });
    // Canvas labels (sky map, charts) and the browser's own dialogs.
    const C = CanvasRenderingContext2D.prototype;
    for (const fn of ['fillText', 'strokeText', 'measureText']) {
      const orig = C[fn];
      C[fn] = function (text, ...rest) { return orig.call(this, tr(text), ...rest); };
    }
    for (const fn of ['alert', 'confirm', 'prompt']) {
      const orig = window[fn];
      window[fn] = (msg, ...rest) => orig.call(window, tr(msg), ...rest);
    }
    document.addEventListener('DOMContentLoaded', () => { walk(document.documentElement); document.title = tr(document.title); });
  }

  // ------------------------------------------------------------------ choosing
  function set(l) {
    if (!LANGS.includes(l)) return;
    store.set(l);
    const u = new URL(location.href);
    u.searchParams.delete('lang');
    location.replace(u.toString());
  }
  /** Full-screen "Español / English" choice: shown the first time, or from the settings. */
  function choose() {
    if (document.getElementById('sbLangPick')) return;
    const box = document.createElement('div');
    box.id = 'sbLangPick';
    box.setAttribute('data-no-i18n', '');
    box.innerHTML = `<div class="sb-lang-card">
        <div class="sb-lang-title">Idioma · Language</div>
        <button data-lang="es"><b>Español</b><span>Usar StarBridge en español</span></button>
        <button data-lang="en"><b>English</b><span>Use StarBridge in English</span></button>
        <p>Puedes cambiarlo luego en Ajustes · You can change it later in Settings</p>
      </div>`;
    const css = document.createElement('style');
    css.textContent = `#sbLangPick{position:fixed;inset:0;z-index:200;display:grid;place-items:center;padding:24px;
        background:rgba(0,0,0,.55);-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",system-ui,sans-serif}
      .sb-lang-card{width:min(380px,100%);padding:26px 22px;border-radius:26px;background:rgba(28,30,40,.85);color:#f5f5f7;
        border:1px solid rgba(255,255,255,.14);box-shadow:inset 0 1px 0 rgba(255,255,255,.2),0 20px 60px rgba(0,0,0,.5);text-align:center}
      .sb-lang-title{font-size:22px;font-weight:700;letter-spacing:-.02em;margin-bottom:18px}
      .sb-lang-card button{display:block;width:100%;margin:10px 0;padding:14px 18px;border:0;border-radius:18px;cursor:pointer;text-align:left;
        background:rgba(255,255,255,.08);color:inherit;font:inherit;box-shadow:inset 0 0 0 1px rgba(255,255,255,.12)}
      .sb-lang-card button:hover{background:rgba(10,132,255,.35)}
      .sb-lang-card b{display:block;font-size:17px}.sb-lang-card span{font-size:13px;opacity:.7}
      .sb-lang-card p{font-size:12px;opacity:.6;margin:14px 0 0}`;
    box.appendChild(css);
    box.addEventListener('click', (e) => {
      const b = e.target.closest('[data-lang]');
      if (!b) return;
      if (b.dataset.lang === lang && chosen) { box.remove(); return; }
      store.set(b.dataset.lang);
      if (b.dataset.lang === lang) box.remove(); else set(b.dataset.lang);
    });
    (document.body || document.documentElement).appendChild(box);
  }
  if (!chosen) document.addEventListener('DOMContentLoaded', choose);

  window.I18N = { lang, chosen: !!chosen, t: tr, set, choose };
})();
